/** A new node for the host type `type` (`GtkButton`), or null when there is no such widget. */
export function createNode(type: string): HostNode | null {
  switch (type) {
    case "GtkAboutDialog":
      return new AboutDialogNode();
    case "GtkActionBar":
      return new ActionBarNode();
    case "GtkApplicationWindow":
      return new ApplicationWindowNode();
    case "GtkAspectFrame":
      return new AspectFrameNode();
    case "GtkBox":
      return new BoxNode();
    case "GtkButton":
      return new ButtonNode();
    case "GtkCalendar":
      return new CalendarNode();
    case "GtkCenterBox":
      return new CenterBoxNode();
    case "GtkCheckButton":
      return new CheckButtonNode();
    case "GtkColorDialogButton":
      return new ColorDialogButtonNode();
    case "GtkColumnView":
      return new ColumnViewNode();
    case "GtkDragIcon":
      return new DragIconNode();
    case "GtkDrawingArea":
      return new DrawingAreaNode();
    case "GtkDropDown":
      return new DropDownNode();
    case "GtkEditableLabel":
      return new EditableLabelNode();
    case "GtkEmojiChooser":
      return new EmojiChooserNode();
    case "GtkEntry":
      return new EntryNode();
    case "GtkExpander":
      return new ExpanderNode();
    case "GtkFixed":
      return new FixedNode();
    case "GtkFlowBox":
      return new FlowBoxNode();
    case "GtkFlowBoxChild":
      return new FlowBoxChildNode();
    case "GtkFontDialogButton":
      return new FontDialogButtonNode();
    case "GtkFrame":
      return new FrameNode();
    case "GtkGLArea":
      return new GLAreaNode();
    case "GtkGraphicsOffload":
      return new GraphicsOffloadNode();
    case "GtkGrid":
      return new GridNode();
    case "GtkGridView":
      return new GridViewNode();
    case "GtkHeaderBar":
      return new HeaderBarNode();
    case "GtkImage":
      return new ImageNode();
    case "GtkInscription":
      return new InscriptionNode();
    case "GtkLabel":
      return new LabelNode();
    case "GtkLevelBar":
      return new LevelBarNode();
    case "GtkLinkButton":
      return new LinkButtonNode();
    case "GtkListBox":
      return new ListBoxNode();
    case "GtkListBoxRow":
      return new ListBoxRowNode();
    case "GtkListView":
      return new ListViewNode();
    case "GtkMediaControls":
      return new MediaControlsNode();
    case "GtkMenuButton":
      return new MenuButtonNode();
    case "GtkNotebook":
      return new NotebookNode();
    case "GtkOverlay":
      return new OverlayNode();
    case "GtkPaned":
      return new PanedNode();
    case "GtkPasswordEntry":
      return new PasswordEntryNode();
    case "GtkPicture":
      return new PictureNode();
    case "GtkPopover":
      return new PopoverNode();
    case "GtkPopoverBin":
      return new PopoverBinNode();
    case "GtkPopoverMenu":
      return new PopoverMenuNode();
    case "GtkPopoverMenuBar":
      return new PopoverMenuBarNode();
    case "GtkProgressBar":
      return new ProgressBarNode();
    case "GtkRange":
      return new RangeNode();
    case "GtkRevealer":
      return new RevealerNode();
    case "GtkScale":
      return new ScaleNode();
    case "GtkScaleButton":
      return new ScaleButtonNode();
    case "GtkScrollbar":
      return new ScrollbarNode();
    case "GtkScrolledWindow":
      return new ScrolledWindowNode();
    case "GtkSearchBar":
      return new SearchBarNode();
    case "GtkSearchEntry":
      return new SearchEntryNode();
    case "GtkSeparator":
      return new SeparatorNode();
    case "GtkSpinButton":
      return new SpinButtonNode();
    case "GtkSpinner":
      return new SpinnerNode();
    case "GtkStack":
      return new StackNode();
    case "GtkStackSidebar":
      return new StackSidebarNode();
    case "GtkStackSwitcher":
      return new StackSwitcherNode();
    case "GtkSwitch":
      return new SwitchNode();
    case "GtkText":
      return new TextNode();
    case "GtkTextView":
      return new TextViewNode();
    case "GtkToggleButton":
      return new ToggleButtonNode();
    case "GtkTreeExpander":
      return new TreeExpanderNode();
    case "GtkVideo":
      return new VideoNode();
    case "GtkViewport":
      return new ViewportNode();
    case "GtkWindow":
      return new WindowNode();
    case "GtkWindowControls":
      return new WindowControlsNode();
    case "GtkWindowHandle":
      return new WindowHandleNode();
  }
  return null;
}
